<script setup lang="ts">
import { imageIndexAtPath } from '~/utils/image-slots'
import { useEditorReturn } from '~/composables/useEditorReturn'
import draggable from 'vuedraggable'
import { plainText, copyRichHtml } from '~/utils/rich-clipboard'
import { ArrowLeft, Plus, Copy, Trash2, GripVertical, Undo2, Redo2, Download, Clipboard, History, LayoutTemplate, ChevronUp, ChevronDown, Settings2, MousePointer2, Layers3, X, Save, Sparkles } from 'lucide-vue-next'
import { elementInfo, patchElement, articleHtml, normalizeAppearance, normalizePalette, sanitizeHtml, htmlAssetIds, newBlockId, cloneSnapshot, prepareComponent, prepareArticleComponent, normalizeTextStyles, extractFieldValues, type ComponentData, type Block, type Article, type ArticleTextStyles, type Resource } from '@qinbian/shared'
const props=withDefaults(defineProps<{id:string;target?:'document'|'resource'}>(),{target:'document'})
const returnTo=useEditorReturn()
const inspectMode=ref(false),inspection=ref<{blockId:string;path:number[]}|null>(null),inspectedComputed=ref<Record<string,string>>({}),aiBusy=ref(false),canvasRefs=shallowRef<Record<string,any>>({})
const inspected=computed(()=>{const b=blocks.value.find(b=>b.id===inspection.value?.blockId);return b&&inspection.value?elementInfo(b.html,inspection.value.path):null})
function toggleInspect(){if(aiBusy.value)return;inspectMode.value=!inspectMode.value;if(!inspectMode.value)inspection.value=null;panel.value=inspectMode.value?'inspect':'properties';rightOpen.value=inspectMode.value}
function inspectElement(key:string,path:number[],computed:Record<string,string>,activate=true){if(!activate){if(inspection.value?.blockId===key)inspectedComputed.value=computed;return}if(aiBusy.value&&inspection.value){ctx.notify('请先完成或取消当前精修');return}selected.value=key;inspection.value={blockId:key,path:[...path]};inspectedComputed.value=computed;if(panel.value!=='ai')panel.value='inspect';rightOpen.value=true}
function inspectParent(path:number[]){if(current.value)canvasRefs.value[current.value.id]?.inspectAt(path)}
function patchInspected(patch:any){if(!current.value||!inspected.value||readonly.value)return;try{updateBlock(current.value.id,patchElement(current.value.html,inspected.value,patch));void nextTick(()=>canvasRefs.value[current.value!.id]?.inspectAt(inspection.value!.path))}catch(e){ctx.error(e)}}
function editInspectedText(){if(!current.value||!inspection.value)return;const key=current.value.id,path=[...inspection.value.path];inspectMode.value=false;inspection.value=null;panel.value='properties';void nextTick(()=>canvasRefs.value[key]?.editAt(path))}
function inspectMedia(){if(!current.value||!inspection.value)return;selectedMedia.value=imageIndexAtPath(current.value.html,inspection.value.path);panel.value='properties'}
function setAiBusy(value:boolean){aiBusy.value=value}
const bindingsEditor=ref<{focusField:(id:string)=>void}>()
function focusDataField(key:string,id:string){choose(key);panel.value='properties';rightOpen.value=true;void nextTick(()=>bindingsEditor.value?.focusField(id))}
const appearance=ref(normalizeAppearance()),backgroundOpen=ref(false),textStyleOpen=ref(false)
function applyWholeStyles(styles:ArticleTextStyles|undefined){const next={...appearance.value};if(styles)next.textStyles=normalizeTextStyles(styles);else delete next.textStyles;blocks.value=blocks.value.map(b=>({...b,...prepareArticleComponent(b,next.textStyles)}));appearance.value=next;textStyleOpen.value=false;activeEditor.value=null;track();ctx.notify(styles?'全文样式已应用':'已停用全文样式')}
function changeBackground(color:string){appearance.value=normalizeAppearance({...appearance.value,backgroundColor:color});track()}
const articlePalette=computed(()=>normalizePalette(ctx.themes.value.find(t=>t.id===themeSetId.value)?.palette))
const generation=ref<''|'component'|'chart'|'divider'>(''),dividerOpen=ref(false)
const ctx=useQinbian(),entity=ref<any>(),title=ref(''),themeSetId=ref('mine'),blocks=ref<Block[]>([]),selected=ref(''),resourcesList=ref<Resource[]>([]),selectedMedia=ref(0),width=ref(375),panel=ref<'properties'|'ai'|'inspect'>('properties'),leftOpen=ref(false),rightOpen=ref(false),activeEditor=shallowRef<any>(null),activeEditorBlock=ref(''),status=ref('正在打开…'),historyOpen=ref(false),versions=ref<any[]>([]),sourceOpen=ref(false),sourceCode=ref(''),manualCopy=ref(''),recover=ref<any>(null)
const revision=ref(1),loading=ref(true),dirty=ref(false),saving=ref(false),history=ref<string[]>([]),historyAt=ref(0)
let saveTimer:ReturnType<typeof setTimeout>|undefined,savePromise:Promise<void>|undefined,saved='',disposed=false
const endpoint=computed(()=>props.target==='document'?'/api/documents/':'/api/resources/')
const key=computed(()=>`qinbian-recovery-${props.target}-${props.id}`)
const current=computed(()=>blocks.value.find(b=>b.id===selected.value))
const readonly=computed(()=>!!entity.value?.builtin)
async function refreshResources(){resourcesList.value=await apiFetch<Resource[]>('/api/resources',{query:{kind:'component'}})}
function beginGenerate(kind:'component'|'chart'|'divider'){if(kind==='divider')dividerOpen.value=true;else generation.value=kind}
async function editResource(resource:Resource){try{await saveNow();let r=resource;if(r.builtin)r=await apiFetch<Resource>('/api/resources/'+r.id+'/clone',{method:'POST',body:{themeSetId:'mine'}});await navigateTo({path:'/resources/'+r.id,query:{returnTo:props.target==='document'?'/documents/'+props.id:'/documents'}})}catch(e){ctx.error(e)}}
async function generatedDivider(r:Resource,shouldInsert:boolean){dividerOpen.value=false;await refreshResources();if(shouldInsert)insert(r)}
async function generated(result:any){await aiApplied(result);await refreshResources()}
const snapshot=()=>JSON.stringify({title:title.value,themeSetId:themeSetId.value,blocks:blocks.value,appearance:appearance.value})
function cache(){localStorage.setItem(key.value,JSON.stringify({revision:revision.value,...JSON.parse(snapshot()),at:Date.now()}))}
function queue(){if(loading.value||readonly.value)return;dirty.value=true;status.value='尚未保存';cache();clearTimeout(saveTimer);saveTimer=setTimeout(()=>void saveNow().catch(()=>{}),650)}
function track(){const s=snapshot();if(s!==history.value[historyAt.value]){history.value=history.value.slice(0,historyAt.value+1);history.value.push(s);if(history.value.length>100)history.value.shift();historyAt.value=history.value.length-1}queue()}
async function load(){loading.value=true;try{const d=await apiFetch<any>(endpoint.value+props.id);entity.value=d;title.value=props.target==='document'?d.title:d.name;themeSetId.value=d.themeSetId;blocks.value=structuredClone(props.target==='document'?d.blocks:d.data.blocks||[]).map((b:Block)=>({...b,...prepareArticleComponent(b,normalizeAppearance(props.target==='document'?d.appearance:d.data.appearance).textStyles)}));appearance.value=normalizeAppearance(props.target==='document'?d.appearance:d.data.appearance);revision.value=d.revision;selected.value=blocks.value.some(b=>b.id===selected.value)?selected.value:blocks.value[0]?.id||'';saved=snapshot();dirty.value=false;status.value=readonly.value?'内置模板 · 只读':'已保存';history.value=[saved];historyAt.value=0;const cached=localStorage.getItem(key.value);if(cached){try{const c=JSON.parse(cached);if(c.at>new Date(d.updatedAt).getTime()&&JSON.stringify({title:c.title,themeSetId:c.themeSetId,blocks:c.blocks,appearance:normalizeAppearance(c.appearance)})!==saved)recover.value=c;else localStorage.removeItem(key.value)}catch{}}}catch(e){ctx.error(e)}finally{loading.value=false}}
onMounted(async()=>{await load();try{await refreshResources()}catch(e){ctx.error(e)}})
async function saveNow(){
 clearTimeout(saveTimer);if(readonly.value||loading.value)return
 if(savePromise){await savePromise;return saveNow()}
 const snap=snapshot();if(snap===saved){dirty.value=false;return}
 const body=props.target==='document'?{title:title.value||'未命名文章',themeSetId:themeSetId.value,blocks:blocks.value,appearance:appearance.value,revision:revision.value}:{...entity.value,name:title.value||'未命名模板',themeSetId:themeSetId.value,data:{blocks:blocks.value,appearance:appearance.value},revision:revision.value}
 saving.value=true;status.value='正在保存…'
 savePromise=(async()=>{try{const d=await apiFetch<any>(endpoint.value+props.id,{method:'PUT',body});revision.value=d.revision;entity.value=d;saved=snap;dirty.value=snapshot()!==snap;status.value=dirty.value?'尚未保存':'已保存';if(!dirty.value)localStorage.removeItem(key.value);else cache()}catch(e){dirty.value=true;status.value='保存失败';cache();ctx.error(e);throw e}finally{saving.value=false;savePromise=undefined}})()
 await savePromise;if(dirty.value&&!disposed)queue()
}
function discardRecovery(){recover.value=null;localStorage.removeItem(key.value)}
function recovered(){if(!recover.value)return;title.value=recover.value.title;themeSetId.value=recover.value.themeSetId;blocks.value=recover.value.blocks;appearance.value=normalizeAppearance(recover.value.appearance);recover.value=null;track()}
function updateBlock(key:string,html:string){const b=blocks.value.find(b=>b.id===key);if(!b||readonly.value)return;const cleaned=sanitizeHtml(html);if(cleaned===b.html)return;b.html=cleaned;b.values={...b.values,...extractFieldValues(cleaned,b.fields||[])};if(appearance.value.textStyles||cleaned.includes('data-qb-chart'))Object.assign(b,prepareArticleComponent(b,appearance.value.textStyles));b.assetIds=htmlAssetIds(b.html);track()}
function updateSettings(data:ComponentData){if(!current.value||readonly.value)return;Object.assign(current.value,prepareArticleComponent(data,appearance.value.textStyles));current.value.assetIds=htmlAssetIds(current.value.html);track()}
function choose(key:string){if(aiBusy.value&&inspection.value&&selected.value!==key){ctx.notify('请先完成或取消当前精修');return}if(selected.value!==key){inspection.value=null;activeEditor.value=null;selectedMedia.value=0}selected.value=key}
function editor(key:string,e:any){if(e){activeEditorBlock.value=key;activeEditor.value=e}else if(activeEditorBlock.value===key)activeEditor.value=null}
function insert(r:Resource){if(readonly.value)return;const b:Block={...cloneSnapshot(r.data),id:newBlockId(),sourceComponentId:r.id,legacyId:r.legacyId,name:r.name,html:r.data.html||'',assetIds:htmlAssetIds(r.data.html||'')};const at=blocks.value.findIndex(b=>b.id===selected.value);Object.assign(b,prepareArticleComponent(b,appearance.value.textStyles));blocks.value.splice(at<0?blocks.value.length:at+1,0,b);selected.value=b.id;track();ctx.notify('已插入组件');leftOpen.value=false}
function duplicate(key:string){const at=blocks.value.findIndex(b=>b.id===key);if(at<0)return;const b=cloneSnapshot(blocks.value[at]!);b.id=newBlockId();blocks.value.splice(at+1,0,b);selected.value=b.id;track()}
function remove(key:string){const at=blocks.value.findIndex(b=>b.id===key);blocks.value.splice(at,1);selected.value=blocks.value[Math.min(at,blocks.value.length-1)]?.id||'';track()}
function move(key:string,delta:number){const at=blocks.value.findIndex(b=>b.id===key),next=at+delta;if(next<0||next>=blocks.value.length)return;const [b]=blocks.value.splice(at,1);blocks.value.splice(next,0,b!);track()}
function undo(){if(historyAt.value===0)return;historyAt.value--;applyHistory()};function redo(){if(historyAt.value>=history.value.length-1)return;historyAt.value++;applyHistory()}
function applyHistory(){const s=JSON.parse(history.value[historyAt.value]!);title.value=s.title;themeSetId.value=s.themeSetId;blocks.value=s.blocks;appearance.value=normalizeAppearance(s.appearance);activeEditor.value=null;if(!blocks.value.some(b=>b.id===selected.value))selected.value=blocks.value[0]?.id||'';queue()}
async function exported(){await saveNow();if(props.target==='document')return await apiFetch<{html:string;title:string}>(endpoint.value+props.id+'/export');return await apiFetch<{html:string}>('/api/export',{method:'POST',body:{html:articleHtml(blocks.value,appearance.value)}})}
async function download(){try{const r=await exported();downloadFile(new Blob(['<!doctype html><html lang="zh-CN"><meta charset="utf-8"><body>'+r.html+'</body></html>'],{type:'text/html;charset=utf-8'}),title.value+'.html');ctx.notify('正文已下载')}catch(e){ctx.error(e)}}
async function copy(){
 const result=exported()
 // Start the clipboard write during the click, before saving/exporting finishes (Safari).
 try{
  if(!navigator.clipboard?.write||typeof ClipboardItem==='undefined')throw new Error('manual')
  const html=result.then(r=>new Blob([r.html],{type:'text/html'})),text=result.then(r=>new Blob([plainText(r.html)],{type:'text/plain'}))
  await navigator.clipboard.write([new ClipboardItem({'text/html':html,'text/plain':text})]);ctx.notify('正文已复制')
 }catch{try{const r=await result;if(copyRichHtml(r.html))ctx.notify('正文已复制');else manualCopy.value=r.html}catch(e){ctx.error(e)}}
}
async function template(){try{await saveNow();if(props.target==='document'){await apiFetch(endpoint.value+props.id+'/template',{method:'POST',body:{name:title.value+' 模板',themeSetId:ctx.themes.value.find(t=>t.id===themeSetId.value&&!t.builtin)?.id||'mine'}});ctx.notify('已另存为模板')}else{const d=await apiFetch<any>('/api/documents',{method:'POST',body:{resourceId:props.id}});navigateTo('/documents/'+d.id)}}catch(e){ctx.error(e)}}
async function openVersions(){await saveNow().catch(()=>{});try{versions.value=await apiFetch<any[]>(endpoint.value+props.id+'/versions');historyOpen.value=true}catch(e){ctx.error(e)}}
async function restoreVersion(v:any){if(!confirm('恢复到这个版本？'))return;try{await apiFetch(endpoint.value+props.id+`/versions/${v.revision}/restore`,{method:'POST',body:{revision:revision.value}});historyOpen.value=false;localStorage.removeItem(key.value);await load();ctx.notify('已恢复所选版本')}catch(e){ctx.error(e)}}
async function aiApplied(result:any){if(result.value?.id===props.id){localStorage.removeItem(key.value);await load()}}
function applyCode(){if(current.value){updateBlock(current.value.id,sourceCode.value);sourceOpen.value=false}}
onBeforeRouteLeave(async()=>{if(dirty.value){try{await saveNow()}catch{return confirm('改动尚未保存。仍要离开吗？')}}return true})
onBeforeUnmount(()=>{disposed=true;clearTimeout(saveTimer);if(dirty.value)cache()})
</script>
<template><div class="workbench"><header class="workbench-heading"><NuxtLink :to="target==='document'?'/documents':returnTo" class="icon-button" aria-label="返回列表"><ArrowLeft :size="19"/></NuxtLink><div class="workbench-title"><input v-model="title" :readonly="readonly" aria-label="文章名称" @input="track"><span :class="{unsaved:dirty}">{{status}}</span></div><div class="workbench-actions"><button class="icon-button" :class="{active:inspectMode}" title="点选元素" aria-label="点选元素" :aria-pressed="inspectMode" :disabled="readonly||aiBusy" @click="toggleInspect"><MousePointer2 :size="17"/></button><button class="icon-button" title="撤销" aria-label="撤销编排" :disabled="historyAt===0||readonly" @click="undo"><Undo2 :size="17"/></button><button class="icon-button" title="重做" aria-label="重做编排" :disabled="historyAt>=history.length-1||readonly" @click="redo"><Redo2 :size="17"/></button><button class="icon-button" title="历史版本" aria-label="历史版本" @click="openVersions"><History :size="17"/></button><span class="toolbar-sep"/><button class="btn compact-button" @click="template"><LayoutTemplate :size="15"/><span>{{target==='document'?'另存模板':'套用模板'}}</span></button><button class="icon-button" title="下载正文" aria-label="下载正文" @click="download"><Download :size="17"/></button><button class="btn primary" @click="copy"><Clipboard :size="15"/><span>复制正文</span></button></div></header>
 <div v-if="recover" class="recovery-banner">有一份未保存的本地改动。<button class="text-button" @click="recovered">恢复</button><button class="text-button" @click="discardRecovery">丢弃</button></div>
 <div class="mobile-workspace-controls"><button class="btn" @click="leftOpen=!leftOpen"><Layers3 :size="15"/>大纲与组件</button><button class="btn" @click="rightOpen=!rightOpen"><Settings2 :size="15"/>设置与 AI</button></div>
 <div class="workspace-columns"><aside class="workspace-left" :class="{drawerOpen:leftOpen}"><div class="workspace-panel-head"><h3>大纲 <small>{{blocks.length}}</small></h3><button class="drawer-close icon-button" aria-label="关闭组件面板" @click="leftOpen=false"><X :size="16"/></button></div><draggable v-model="blocks" item-key="id" handle=".outline-grip" class="article-outline" :disabled="readonly" @end="track"><template #item="{element,index}"><div class="outline-item" :class="{selected:element.id===selected}" @click="choose(element.id)"><GripVertical :size="14" class="outline-grip"/><span class="outline-number">{{String(index+1).padStart(2,'0')}}</span><span>{{element.name}}</span></div></template></draggable><div class="panel-rule"/><ComponentShelf :items="resourcesList" :theme-set-id="themeSetId" :readonly="readonly" @insert="insert" @refresh="refreshResources" @edit="editResource" @generate="beginGenerate"/></aside>
 <section class="workspace-center"><RichToolbar :editor="activeEditor" :palette="current?.palette" :mappings="current?.colorMappings"/><div class="paper-options"><div class="preview-width-tabs"><button v-for="w in [320,375,414]" :key="w" :class="{active:width===w}" @click="width=w">{{w}}</button></div><span>{{blocks.length}} 个组件</span></div><div class="canvas-paper" :style="{width:width+'px',backgroundColor:appearance.backgroundColor}"><div v-if="!blocks.length" class="canvas-empty"><Layers3 :size="36"/><h3>空白文章</h3><p>从左侧插入组件，或用 AI 生成。</p><button class="btn" @click="leftOpen=true"><Plus :size="15"/>插入组件</button></div><draggable v-model="blocks" item-key="id" handle=".canvas-grip" :disabled="readonly" @end="track"><template #item="{element,index}"><div class="canvas-block-wrap" :class="{chosen:element.id===selected}"><div v-if="element.id===selected&&!readonly" class="canvas-block-actions"><span class="canvas-grip" title="拖动排序"><GripVertical :size="15"/></span><small>{{element.name}}</small><button aria-label="上移选中组件" :disabled="index===0" @click="move(element.id,-1)"><ChevronUp :size="14"/></button><button aria-label="下移选中组件" :disabled="index===blocks.length-1" @click="move(element.id,1)"><ChevronDown :size="14"/></button><button aria-label="复制选中组件" @click="duplicate(element.id)"><Copy :size="13"/></button><button aria-label="移除选中组件" @click="remove(element.id)"><Trash2 :size="13"/></button></div><CanvasBlock :ref="el=>{if(el)canvasRefs[element.id]=el;else delete canvasRefs[element.id]}" :html="element.html" :inspect="inspectMode" :inspected-path="inspection?.blockId===element.id?inspection?.path:undefined" @inspect="(path,computed,activate)=>inspectElement(element.id,path,computed,activate)" @inspect-exit="toggleInspect" :selected="element.id===selected" :readonly="readonly" @update="html=>updateBlock(element.id,html)" @select="choose(element.id)" @editor="e=>editor(element.id,e)" @field="id=>focusDataField(element.id,id)" @media="n=>{choose(element.id);selectedMedia=n;panel='properties';rightOpen=true}"/></div></template></draggable></div></section>
 <aside class="workspace-right" :class="{drawerOpen:rightOpen}"><div class="workspace-panel-head"><div class="mini-tabs"><button v-if="inspectMode" :class="{active:panel==='inspect'}" @click="panel='inspect'">点选属性</button><button :class="{active:panel==='properties'}" @click="panel='properties'">组件设置</button><button :class="{active:panel==='ai'}" @click="panel='ai'"><Sparkles :size="13"/>AI 制作</button></div><button class="drawer-close icon-button" aria-label="关闭设置面板" @click="rightOpen=false"><X :size="16"/></button></div><template v-if="panel==='properties'"><div v-if="current" class="selected-component-note"><span class="eyebrow">当前组件</span><h3>{{current.name}}</h3></div><ComponentBindings ref="bindingsEditor" v-if="current&&!readonly" :data="current" :theme-set-id="themeSetId" @update="updateSettings"/><MediaInspector v-if="current&&!readonly" :key="current.id" :html="current.html" :media-index="selectedMedia" :legacy-id="current.legacyId" @update="html=>updateBlock(current!.id,html)"/><div v-if="current&&!readonly" class="advanced-entry"><button class="text-button" @click="sourceCode=current!.html;sourceOpen=true">编辑源码</button></div><div class="document-properties"><h4>整篇文章</h4><button class="btn full" :disabled="readonly" aria-label="设置全文样式" @click="textStyleOpen=true">全文样式</button><UiSelect v-model="themeSetId" :options="ctx.themes.value.map(t=>({value:t.id,label:t.name}))" :disabled="readonly" aria-label="文章主题套组" @change="track"/><div class="article-background-control"><label>文章背景</label><button class="article-background-button" :disabled="readonly" aria-label="修改整篇文章背景" @click="backgroundOpen=true"><i :style="{background:appearance.backgroundColor}"/><span>{{appearance.backgroundColor}}</span><span>修改</span></button><div class="article-background-presets"><button v-for="c in ['#FFFFFF','#FFFCF6','#EEF3EB','#F7ECE9']" :key="c" :disabled="readonly" :aria-label="'背景 '+c" :class="{selected:appearance.backgroundColor===c}" :style="{background:c}" @click="changeBackground(c)"/></div></div><button v-if="!readonly" class="btn full" :disabled="saving" @click="saveNow().catch(()=>{})"><Save :size="14"/>{{saving?'正在保存…':'立即保存'}}</button></div></template><ElementInspector v-if="panel==='inspect'" :info="inspected" :computed-styles="inspectedComputed" :palette="current?.palette" :mappings="current?.colorMappings" :fields="current?.fields" @select="inspectParent" @patch="patchInspected" @ai="panel='ai'" @edit-text="editInspectedText" @media="inspectMedia"/><AiPanel v-if="!loading" v-show="panel==='ai'" allow-insert :background-color="appearance.backgroundColor" :theme-set-id="themeSetId" :target-type="target" :target-id="id" :target-revision="revision" :block-id="current?.id" :source-html="inspectMode&&inspected?inspected.html:current?.html" :selection="inspectMode&&inspected?{path:inspected.path,fingerprint:inspected.fingerprint}:undefined" :text-styles="appearance.textStyles" :settings="current" :before-start="saveNow" @busy="setAiBusy" @applied="aiApplied"/></aside>
 </div>
 <UiModal v-if="historyOpen" title="历史版本" @close="historyOpen=false"><div class="version-list"><div v-for="v in versions" :key="v.id"><span>第 {{v.revision}} 版<small>{{formatDate(v.createdAt)}}</small></span><button class="btn" :disabled="v.revision===revision||readonly" @click="restoreVersion(v)">{{v.revision===revision?'当前':'恢复'}}</button></div><p v-if="!versions.length" class="muted">暂无历史版本。</p></div></UiModal>
 <UiModal v-if="sourceOpen" title="组件源码" wide @close="sourceOpen=false"><textarea v-model="sourceCode" class="source-editor" rows="18" spellcheck="false"/><div class="modal-actions"><button class="btn primary" @click="applyCode">应用</button></div></UiModal>
 <DividerComposer v-if="dividerOpen" :theme-set-id="themeSetId" :palette="current?.palette" @close="dividerOpen=false" @custom="dividerOpen=false;generation='divider'" @created="generatedDivider"/>
 <UiModal v-if="generation" :title="generation==='chart'?'生成数据图':generation==='divider'?'AI 设计分隔符':'AI 生成组件'" @close="generation=''" ><AiPanel allow-insert :background-color="appearance.backgroundColor" :purpose="generation" :theme-set-id="themeSetId" :target-type="readonly?undefined:target" :target-id="readonly?undefined:id" :target-revision="revision" :before-start="saveNow" @applied="generated"/></UiModal>
 <ArticleStyleEditor v-if="textStyleOpen" :blocks="blocks" :appearance="appearance" :selected-id="selected" @close="textStyleOpen=false" @apply="applyWholeStyles"/>
 <ColorPicker v-if="backgroundOpen" title="整篇文章背景" :palette="articlePalette" :current="appearance.backgroundColor" @close="backgroundOpen=false" @choose="choice=>{changeBackground(choice.value);backgroundOpen=false}"/>
 <CopyBodyModal v-if="manualCopy" :html="manualCopy" @close="manualCopy=''"/>
 </div></template>
